import React, { useEffect, useState, useRef } from 'react';
import { MessageCircle, Send, Bot, User, Video } from 'lucide-react';
import './ChatPage.css';

const LiveChat = () => {
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState('');
  const [ws, setWs] = useState(null);
  const [isConnected, setIsConnected] = useState(false);
  const [isStreaming, setIsStreaming] = useState(false);
  const messagesEndRef = useRef(null);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const connectWebSocket = () => {
    const socket = new WebSocket('ws://localhost:8000/ws/voicechat');
    socket.onopen = () => {
      console.log('WebSocket connected');
      setWs(socket);
      setIsConnected(true);
    };

    socket.onmessage = (event) => {
      const msg = JSON.parse(event.data);

      if (msg.type === 'agent_text_partial') {
        setIsStreaming(true);
        updateLastBotMessage(msg.text);
      }

      if (msg.type === 'agent_text_final') {
        updateLastBotMessage(msg.text);
        setIsStreaming(false);
        speak(msg.text);
      }
    };

    socket.onclose = () => {
      console.log('WebSocket disconnected');
      setWs(null);
      setIsConnected(false);
    };
  };

  const speak = (text) => {
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = 'en-US';
    speechSynthesis.speak(utterance);
  };

  const updateLastBotMessage = (text) => {
    setMessages(prev => {
      const updated = [...prev];
      if (updated.length > 0 && updated[updated.length - 1].sender === 'bot') {
        updated[updated.length - 1].text = text;
      }
      return updated;
    });
  };

  const handleSend = () => {
    if (!input.trim() || !ws) return;
    const userText = input.trim();
    setMessages(prev => [
      ...prev,
      { sender: 'user', text: userText, timestamp: new Date().toLocaleTimeString() },
      { sender: 'bot', text: '', timestamp: new Date().toLocaleTimeString() }
    ]);
    setInput('');
    ws.send(JSON.stringify({ type: 'asr_end', text: userText }));
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  return (
    <div className="chat-page page-transition">
      <div className="container">
        <div className="page-header">
          <h1 className="page-title">
            <MessageCircle className="page-icon" /> Live Voice Chat Assistant
          </h1>
          <p className="page-subtitle">Talk to your farming assistant in real time!</p>
        </div>

        <div className="chat-container">
          <div className="chat-messages">
            {messages.map((msg, i) => (
              <div key={i} className={`message ${msg.sender === 'user' ? 'user-message' : 'bot-message'}`}>
                <div className="message-avatar">
                  {msg.sender === 'user' ? <User className="avatar-icon" /> : <Bot className="avatar-icon" />}
                </div>
                <div className="message-content">
                  <div className="message-text">{msg.text}</div>
                  <div className="message-time">{msg.timestamp}</div>
                </div>
              </div>
            ))}
            {isStreaming && (
              <div className="message bot-message">
                <div className="message-avatar"><Bot className="avatar-icon" /></div>
                <div className="message-content">
                  <div className="typing-indicator">
                    <div className="typing-dot"></div>
                    <div className="typing-dot"></div>
                    <div className="typing-dot"></div>
                  </div>
                </div>
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>

          {!isConnected ? (
            <div className="connect-container">
              <button className="connect-btn" onClick={connectWebSocket}>
                <Video className="mr-2" /> Start Live Chat
              </button>
            </div>
          ) : (
            <div className="chat-input-container">
              <div className="chat-input-wrapper">
                <textarea
                  className="chat-input"
                  placeholder="Say something..."
                  value={input}
                  onChange={(e) => setInput(e.target.value)}
                  onKeyPress={handleKeyPress}
                  rows="1"
                />
                <div className="input-actions">
                  <button
                    className="send-btn"
                    onClick={handleSend}
                    disabled={!input.trim()}
                  >
                    <Send />
                  </button>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default LiveChat;
